/** The MHPCO price list for main items: base premium in G per item type. */
const MAIN_ITEM_BASE_PREMIUM_G: Readonly<Record<string, number>> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

/**
 * Components — runes, moonstones and their kin — are not listed individually on
 * the main price list. MHPCO charges one uniform rate per component.
 */
const COMPONENT_BASE_PREMIUM_G = 25;

const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

/** The base premium of a single item according to the MHPCO price list. */
function itemBasePremium(item: Item): number {
  return isComponent(item) ? COMPONENT_BASE_PREMIUM_G : MAIN_ITEM_BASE_PREMIUM_G[item.type];
}

/** The sum of the base premiums of all insured items, before any modifier. */
function policyBasePremium(items: readonly Item[]): number {
  return items.reduce((sum, item) => sum + itemBasePremium(item), 0);
}

