/**
 * The MHPCO price list: what each insured thing costs before any modifier.
 *
 * This module owns catalogue knowledge only — which item types the office
 * recognises and the base premium it charges for them. It deliberately knows
 * nothing about surcharges, discounts, the processing fee or rounding: those
 * are underwriting policy and change for entirely different reasons.
 */

export interface Item {
  readonly type: string;
}

/** The MHPCO price list for main items: base premium in G per item type. */
const MAIN_ITEM_BASE_PREMIUM_G: Readonly<Record<string, number>> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

